glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec3 light = vec3(0.25);
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    vec2 p = vec2(0.5 + 0.38 * sin(uTime * (0.9 + fi * 0.3) + fi * 2.0), 0.5 + 0.35 * cos(uTime * (1.1 + fi * 0.2) + fi));
    vec2 d = (uv - p) * vec2(uRatio, 1.0);
    vec3 col = fi < 0.5 ? vec3(1.0, 0.2, 0.5) : fi < 1.5 ? vec3(0.2, 0.6, 1.0) : vec3(0.3, 1.0, 0.4);
    light += col * smoothstep(0.35, 0.0, length(d)) * 1.3;
  }
  return vec4(mix(c.rgb, c.rgb * light, uAmount), c.a);
}
